#!/usr/bin/env node
// Validates the generated learning manifest against the shared contract and
// proves every cross reference it claims: planner coverage, recovery table
// integrity, guide and scenario references, and the three availability
// dimensions. The manifest is generated by the shared package's generator and
// is never hand-edited; this gate fails the build when it is stale or wrong.
import { readFileSync } from 'node:fs'
import { join, resolve, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import {
  parseManifest,
  planGoal,
  auditRecoveryTable,
  buildInscribeLink,
} from '@universe/inscribe-learning'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const manifest = parseManifest(JSON.parse(readFileSync(join(root, 'data', 'inscribe-learning.manifest.json'), 'utf8')))

const problems = []

// Provenance: all three source commits must be present and distinct repos.
for (const repo of ['inscribe', 'docs-platform', 'docs-inscribe']) {
  const commit = manifest.sourceCommits[repo]
  if (!/^[0-9a-f]{40}$/.test(commit)) problems.push(`sourceCommits.${repo} is not a full commit`)
}

// Planner coverage: every actionable goal resolves, in every priority.
const goals = [...new Set(manifest.workflows.filter((w) => w.state.actionable).map((w) => w.goal))]
for (const goal of goals) {
  for (const priority of ['simplest', 'cheapest', 'control', 'batch_efficiency', 'urgency']) {
    const result = planGoal(manifest, {
      goal,
      protocol: 'help_me_choose',
      chain: 'bitcoin',
      network: 'mainnet',
      wallet: 'unknown',
      receivingAddressReady: true,
      experience: 'intermediate',
      priority,
      practiceFirst: false,
    })
    if (!result.recommended) problems.push(`planner coverage: goal ${goal} priority ${priority} resolves to nothing`)
    if (!result.recommended?.scoreBreakdown.length) problems.push(`planner coverage: goal ${goal} has no score breakdown`)
  }
}

// Excluded, gated, and read-only states must exist and be presented honestly.
const gated = manifest.protocols.filter((p) => p.state.implemented && !p.state.enabled)
const readOnly = manifest.protocols.filter((p) => !p.state.actionable)
if (manifest.workflows.some((w) => !w.state.implemented && w.state.actionable)) {
  problems.push('an incomplete workflow is marked actionable')
}

// Recovery table integrity.
const outcomeIds = manifest.recovery.outcomes.map((o) => `outcome:${o.id}`)
const audit = auditRecoveryTable(manifest.recovery.table, outcomeIds)
for (const id of audit.unreachable) problems.push(`recovery question unreachable: ${id}`)
for (const loop of audit.loops) problems.push(`recovery loop: ${loop.from} -> ${loop.to}`)
for (const id of audit.missingOutcomes) problems.push(`recovery outcome missing: ${id}`)

// References.
for (const workflow of manifest.workflows) {
  for (const guideId of workflow.guides) {
    if (!manifest.guides.some((g) => g.id === guideId)) problems.push(`${workflow.id}: missing guide ${guideId}`)
  }
  if (workflow.practiceScenarioId && !manifest.practiceScenarios.some((s) => s.id === workflow.practiceScenarioId)) {
    problems.push(`${workflow.id}: missing practice scenario ${workflow.practiceScenarioId}`)
  }
  if (workflow.walkthroughId && !manifest.walkthroughs.some((w) => w.id === workflow.walkthroughId)) {
    problems.push(`${workflow.id}: missing walkthrough ${workflow.walkthroughId}`)
  }
}
for (const outcome of manifest.recovery.outcomes) {
  if (outcome.guideId && !manifest.guides.some((g) => g.id === outcome.guideId)) {
    problems.push(`recovery outcome ${outcome.id}: missing guide ${outcome.guideId}`)
  }
}

// Practice registry and the manifest must agree one to one.
const registry = JSON.parse(readFileSync(join(root, 'data', 'practice-scenarios.json'), 'utf8'))
const manifestIds = new Set(manifest.practiceScenarios.map((s) => s.id))
for (const scenario of registry.scenarios) {
  if (!manifestIds.has(scenario.id)) problems.push(`registry scenario ${scenario.id} is not in the manifest`)
}
if (manifestIds.size !== registry.scenarios.length) problems.push('manifest has scenarios the registry does not list')

if (problems.length > 0) {
  console.error(`check-learning-manifest: ${problems.length} problem(s):`)
  for (const problem of problems) console.error(`  - ${problem}`)
  process.exit(1)
}
console.log(`check-learning-manifest: ${manifest.workflows.length} workflows, ${manifest.protocols.length} protocols (${gated.length} gated, ${readOnly.length} non-actionable), ${manifest.recovery.outcomes.length} recovery outcomes proven`)
